const int NUM_SPHERES = 4;  // Define array size
const int NUM_SM2S = 4;  // Define array size


// Struct for a sphere
struct Sphere {
    vec3 center;
    float radius;
    vec3 color;
};

struct SphereMinus2 {
    vec3 center;
    Sphere main_sphere;
    Sphere sub_sphere1;
    Sphere sub_sphere2;
};


// Ray structure
struct Ray {
    vec3 origin;
    vec3 direction;
};


// Struct to encapsulate ray-sphere intersection results
struct IntersectionResult {
    bool hit;        // Whether the ray hits the sphere
    int type;        // 1 == Sphere, 2 == S2M
    int index;       // index in arrays
    float t1;        // Distance to the first intersection point
    float t2;        // Distance to the second intersection point
    vec3 hitpoint;
    vec3 n;          // Normal at the nearest intersection point
    vec3 col;        // Color of the sphere
};


// Hash functions based on Inigo Quilez's procedural generation work
// Adapted from ShaderToy examples and public domain snippets

// Noise functions
float hash(vec2 p) {
    p = 50.0 * fract(p * 0.3183099 + vec2(0.71, 0.113));
    return -1.0 + 2.0 * fract(p.x * p.y * (p.x + p.y));
}


float hash1D(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

// 2D Hash function
float hash2D(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Generate a random vec3 within given bounds
vec3 randomVec3(vec2 seed, vec3 minBound, vec3 maxBound) {
    // Generate pseudorandom components
    float r1 = hash2D(seed);
    float r2 = hash2D(seed + vec2(1.0, 0.0));
    float r3 = hash2D(seed + vec2(0.0, 1.0));

    // Interpolate between bounds
    return mix(minBound, maxBound, vec3(r1, r2, r3));
}


// Palette based on IQ's work
vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d ) {
    return a + b*cos( 6.283185*(c*t+d) );
}

// Predefined palettes based on IQ's suggestions (flattened for compatibility)
const vec3 PALETTES[28] = vec3[](
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(1.0, 1.0, 1.0), vec3(0.00, 0.33, 0.67),
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(1.0, 1.0, 1.0), vec3(0.00, 0.10, 0.20),
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(1.0, 1.0, 1.0), vec3(0.30, 0.20, 0.20),
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(1.0, 1.0, 0.5), vec3(0.80, 0.90, 0.30),
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(1.0, 0.7, 0.4), vec3(0.00, 0.15, 0.20),
    vec3(0.5, 0.5, 0.5), vec3(0.5, 0.5, 0.5), vec3(2.0, 1.0, 0.0), vec3(0.50, 0.20, 0.25),
    vec3(0.8, 0.5, 0.4), vec3(0.2, 0.4, 0.2), vec3(2.0, 1.0, 1.0), vec3(0.00, 0.25, 0.25)
);

vec3 getpalette( float value, int index ) {
    return palette(value, PALETTES[index*4], PALETTES[index*4+1], PALETTES[index*4+2], PALETTES[index*4+3]);
}


float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0, 0.0)), 
                   hash(i + vec2(1.0, 0.0)), u.x),
               mix(hash(i + vec2(0.0, 1.0)), 
                   hash(i + vec2(1.0, 1.0)), u.x), u.y);
}

// Fractal Brownian Motion
float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

// Nebula coloring
vec3 surface_nebula(vec2 uv, float brightness_boost) {
    float n = fbm(uv * 4.0); // Scale for nebula detail
    float m = fbm(uv * 2.0 + vec2(5.0)); // Add more layers
    float d = smoothstep(0.2, 0.6, n - m); // Contrast

    // Nebula colors
    vec3 color1 = vec3(0.3, 0.2, .4); // Blue tint
    vec3 color2 = vec3(.3, 0.2, 0.3); // Pink tint
    vec3 color = mix(color1, color2, d);

    return color * (n * brightness_boost); // Brightness boost
}


vec3 rayscene_orbit(vec3 origin, vec3 initialPoint, float speed, vec3 axis, float time, float timeOffset) {
    axis = normalize(axis);
    float angle = time * speed + timeOffset;
    float c = cos(angle);
    float s = sin(angle);
    float t = 1.0 - c;

    mat3 rot = mat3(
        t * axis.x * axis.x + c,        t * axis.x * axis.y - s * axis.z, t * axis.x * axis.z + s * axis.y,
        t * axis.x * axis.y + s * axis.z, t * axis.y * axis.y + c,        t * axis.y * axis.z - s * axis.x,
        t * axis.x * axis.z - s * axis.y, t * axis.y * axis.z + s * axis.x, t * axis.z * axis.z + c
    );

    vec3 relativePoint = initialPoint - origin;
    vec3 rotatedPoint = rot * relativePoint;
    return origin + rotatedPoint;
}


// Function to calculate ray-sphere intersection and return results in a struct
IntersectionResult raytrace_intersectSphere(Ray ray, Sphere sphere) {
    IntersectionResult result;
    result.hit = false; // Default: no hit
    result.type = 1;

    // Compute vector from ray origin to sphere center
    vec3 oc = ray.origin - sphere.center;
    float b = dot(oc, ray.direction);
    float c = dot(oc, oc) - sphere.radius * sphere.radius;
    float h = b * b - c; // Discriminant

    // Check for no intersection
    if (h < 0.0) return result;

    // Calculate both intersection points
    h = sqrt(h);
    result.t1 = -b - h; // Entry point
    result.t2 = -b + h; // Exit point

    // Validate if intersection occurs
    if (result.t1 < 0.0 && result.t2 < 0.0) return result;

    // Set hit flag
    result.hit = true;

    // Use the closest valid intersection point for normal and color
    float t = (result.t1 > 0.0) ? result.t1 : result.t2;
    vec3 hitPoint = ray.origin + t * ray.direction;

    // Compute normal and color
    result.n = normalize(hitPoint - sphere.center);
    result.col = sphere.color;
    result.hitpoint = hitPoint;

    return result;
}



IntersectionResult raytrace_intersect_sphereMinus2(Ray ray, SphereMinus2 sm2) {
    IntersectionResult result;
    result.hit = false; // Default: no hit
    result.col = sm2.main_sphere.color;
    result.type = 2;

    float t0A, t1A, t0B, t1B, t0C, t1C;

    // Intersect the main sphere
    IntersectionResult ir_mainsphere = raytrace_intersectSphere(ray, sm2.main_sphere);
    if (!ir_mainsphere.hit) return result;
    t0A = ir_mainsphere.t1;
    t1A = ir_mainsphere.t2;    

    IntersectionResult ir_Bsphere = raytrace_intersectSphere(ray, sm2.sub_sphere1);
    t0B = ir_Bsphere.t1;
    t1B = ir_Bsphere.t2;

    IntersectionResult ir_Csphere =  raytrace_intersectSphere(ray, sm2.sub_sphere2);
    t0C = ir_Csphere.t1; 
    t1C = ir_Csphere.t2;

    float t0final=t0B, t1final=t1B;
    vec3 sphereFinalCenter;

    if (ir_Bsphere.hit && ir_Csphere.hit) {
        if (t0B < t0C) {
        // B sphere starts before C sphere
            if (t1B<t0C || t1B > t1C) {
            // B sphere ends before C sphere OR engulfs C sphere
                t0final = t0B;
                t1final = t1B;
                sphereFinalCenter = sm2.sub_sphere1.center;
            } else {
            // otherwise tunnel sphere
                t0final = t0B;
                t1final = t1C;
                sphereFinalCenter = sm2.sub_sphere2.center;
            }
        } else {
        // C sphere starts before B sphere
            if (t1C<t0B || t1C > t1B) {
            // C sphere ends before B sphere OR engulfs B sphere
                t0final = t0C;
                t1final = t1C;
                sphereFinalCenter = sm2.sub_sphere2.center;
            } else {
            // otherwise tunnel sphere
                t0final = t0C;
                t1final = t1B;
                sphereFinalCenter = sm2.sub_sphere1.center;
            }
         }            
    } else if (ir_Bsphere.hit) {
        // B sphere is the only one hit
        t0final = t0B;
        t1final = t1B;
        sphereFinalCenter = sm2.sub_sphere1.center;
    } else if (ir_Csphere.hit) {
        // C sphere is the only one hit
        t0final = t0C;
        t1final = t1C;
        sphereFinalCenter = sm2.sub_sphere2.center;
    } else {
        // neither B nor C hit (should optimize)
        result.hit = true;
        result.t1 = t0A;
        result.hitpoint = ir_mainsphere.hitpoint;
        result.n = normalize(result.hitpoint - sm2.main_sphere.center);
        return result;
    }

    // reduced to two interval case t0A, t1A and t0final, t1final

    // Case 1: Outside main sphere and outside subtracting sphere
    if (t0A > 0.0 && (t0A < t0final || t1final < t0A)) {
        result.hit = true;
        result.t1 = t0A;
        result.hitpoint = ir_mainsphere.hitpoint;
        result.n = normalize(result.hitpoint - sm2.main_sphere.center);
        return result;
    }

    // Case 2: Entering the subtracting sphere
    if (t0A > 0.0 && t0final < t0A && t0A < t1final && t1A > t1final) {
        result.hit = true;
        result.t1 = t1final; // Use the exit point of the subtracting sphere
        result.hitpoint = ray.origin + result.t1 * ray.direction;
        result.n = -normalize(result.hitpoint - sphereFinalCenter); // Flip normal for subtraction
        return result;
    }

    return result; // No valid hit
}


IntersectionResult raytrace_traceRay(Ray ray, Sphere spheres[NUM_SPHERES], SphereMinus2 s2ms[NUM_SM2S]) {
    IntersectionResult ir_best;
    ir_best.hit = false;
    ir_best.t1 = 1e6;

    // spheres
    for (int i = 0; i < NUM_SPHERES; i++) {
        IntersectionResult ir = raytrace_intersectSphere(ray, spheres[i]);
        if (ir.hit && ir.t1 < ir_best.t1) {
            ir_best = ir;
            ir_best.index=i;
        }
    }

    // s2ms
    for (int i = 0; i < NUM_SM2S; i++) {
        IntersectionResult ir = raytrace_intersect_sphereMinus2(ray, s2ms[i]);
        if (ir.hit && ir.t1 < ir_best.t1) {
            ir_best = ir;
            ir_best.index=i;
        }
    }

    return ir_best;
}

SphereMinus2 createRing(vec3 center, vec3 axis, float radius, float thickness, vec3 color) {
    axis = normalize(axis); // Ensure the axis is normalized

    // Create the outer and inner spheres
    Sphere outer = Sphere(center, radius, color);
    Sphere inner1 = Sphere(center + axis * (thickness * 0.5), radius + 0.1, color);
    Sphere inner2 = Sphere(center - axis * (thickness * 0.5), radius + 0.1, color);

    SphereMinus2 sm2 = SphereMinus2(vec3(0.0,0.0,0.0), outer, inner1, inner2);
    return sm2;
}

SphereMinus2 createRingPolar(vec3 center, float theta, float phi, float radius, float thickness, vec3 color) {
    vec3 axis = normalize(vec3(
        cos(theta) * cos(phi), // x
        sin(theta) * cos(phi), // y
        sin(phi)               // z
    ));

    return createRing(center, axis, radius, thickness, color);
}

vec3 surface_plasma(float theta, float phi, float time, int index, int col_index) {
    int base = col_index * 4;
    float val = cos(time)*sin(hash1D(float(index))*time+theta) + 
                sin(time) * sin(hash1D(float(index))*(1.1+cos(time*0.01))*time+phi);
    return palette(val, PALETTES[base], PALETTES[base+1], PALETTES[base+2], PALETTES[base+3]);
}

// Calculate lighting
vec3 calculateLighting(Ray ray, vec3 point, vec3 normal, vec3 lightPos, vec3 lightColor, vec3 baseColor) {
    vec3 lightDir = normalize(lightPos - point);
    float diff = max(dot(normal, lightDir), 0.0);

    float spec = pow(max(dot(reflect(-lightDir, normal), -ray.direction), 0.0), 32.0);
    vec3 diffuse = diff * lightColor;

    vec3 ambientLight = vec3(0.2, 0.2, 0.2); // Soft gray ambient light
    return baseColor * diffuse + vec3(1.0) * spec + ambientLight * baseColor;
}


// Always point the camera at target
vec3 rd_towards_point(vec3 target, vec3 ro, vec2 uv) {

    // Compute ray direction
    vec3 forward = normalize(target - ro); // Forward vector (camera direction)
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward)); // Right vector
    vec3 up = cross(forward, right);       // Up vector

    // Convert screen UV coordinates to world space
    vec3 rd = normalize(forward + uv.x * right + uv.y * up); // Adjust ray direction
    return rd;
}


float easeInOut(float t) {
    return t < 0.5 ? 4.0 * t * t * t : 1.0 - pow(-2.0 * t + 2.0, 3.0) / 2.0;
}


vec3 flash_color(float iTime, vec2 uv, float peak_length, float repeat_interval, float size) {
    // Zeitsteuerung für den Blitz
    float t = mod(iTime, repeat_interval); // Wiederholt sich alle 1 Sekunde
    t = smoothstep(0.0, peak_length, t) - smoothstep(0.3, 0.8, t); // Kurzer Peak, dann Abklingen

//    t = easeInOut(iTime);

    // Radialer Blitz
    float dist = length(uv); // Abstand vom Zentrum
    float flash = exp(-size * dist) * t; // Radiale Form kombiniert mit Zeitsteuerung

    // Farbgebung: Weißer Blitz mit einem leichten Helligkeitsgradienten
    return vec3(1.0) * flash;
}

vec3 cartesianToPolar(vec3 v) {
    float r = length(v);                  // Radius (distance)
    float theta = acos(v.y / r);          // Polar angle (Y-axis elevation)
    float phi = atan(v.z, v.x);           // Azimuthal angle (XZ-plane rotation)
    return vec3(r, theta, phi);           // Returns (r, θ, φ)
}

vec3 polarToCartesian(vec3 p) {
    float r = p.x;                        // Radius
    float theta = p.y;                     // Polar angle (Y-axis elevation)
    float phi = p.z;                        // Azimuthal angle (XZ-plane rotation)

    float x = r * sin(theta) * cos(phi);   // X-coordinate
    float y = r * cos(theta);              // Y-coordinate
    float z = r * sin(theta) * sin(phi);   // Z-coordinate

    return vec3(x, y, z);                  // Returns (x, y, z)
}


vec3 flightPathAccel(vec3 start, vec3 end, float t, float duration) {
    // Normalize time between 0 and 1
    t = clamp(t / duration, 0.0, 1.0);

    // Acceleration function (quadratic growth)
    float easeT = t * t; // Accelerates over time

    // Linear interpolation with acceleration
    return mix(start, end, easeT);
}


vec3 flightPathEase(vec3 start, vec3 end, float t, float duration) {
    // Normalize time between 0 and 1
    t = clamp(t / duration, 0.0, 1.0);

    // Smoothstep easing function (accelerate and decelerate)
//    float easeT = smoothstep(0.0, 1.0, t) * t;
    float easeT = easeInOut(t);

    // Linear interpolation with easing
    return mix(start, end, easeT);
}



void rayscene_buildScene(out Sphere spheres[NUM_SPHERES], out SphereMinus2 s2ms[NUM_SM2S], float locTime, float epochnum) {
    vec3 origin = vec3(0.0);
    float timeOffset = 2.0;

    spheres[0] = Sphere(
        origin, 
        0.5, vec3(1.0, 0.5, 0.3)
    );

    spheres[0] = Sphere(
        origin, 
        0.5, getpalette((mod(floor(epochnum), 5.0)), int(mod(floor(epochnum), 5.0)))
    );


    spheres[1] = Sphere(
        rayscene_orbit(origin, vec3(-.5, .5, 0.0), .5, vec3(0.8, 1.0, 0.0), 10.0*locTime, 2.0*timeOffset), 
        0.2, vec3(1.0, 1.0, 1.0)
    );
    spheres[2] = Sphere(
        rayscene_orbit(origin, vec3(.5, .5, 0.0), .5, vec3(-0.8, 1.0, 0.0), 10.0*locTime, 2.0*timeOffset), 
        0.2, vec3(1.0, 1.0, 1.0)
    );
    spheres[3] = Sphere(
        rayscene_orbit(origin, vec3(.5, -.5, 0.5), .5, vec3(-0.8, -1.0, 0.5), 10.0*locTime, 2.0*timeOffset), 
        0.2, vec3(1.0, 1.0, 1.0)
    );


    // S2Ms
    s2ms[0] = createRingPolar(
        origin,
        0.0,
        1.0+locTime,
        2.0,
        1.3 + 0.3*hash2D(vec2(epochnum, 4.0)),
        vec3(1.0, 1.0, .2));    

    s2ms[1] = createRingPolar(
        origin,
        0.0,
        2.0+locTime*1.2,
        2.5,
        1.4 + 0.5* hash2D(vec2(epochnum, 1.0)),
        vec3(1.0, .0, .0));


    s2ms[2] = createRingPolar(
        origin,
        locTime * 0.6,
        1.2 + locTime * (pow(locTime,2.2) * 0.05),
        3.0,
        1.2 + hash2D(vec2(epochnum, 3.0)),
        vec3(.0, .0, 1.0));

    s2ms[3] = createRingPolar(
        origin,
        locTime,
        - locTime,
        1.5,
        1.3 + 0.3*hash2D(vec2(epochnum, 9.0)),
        vec3(1.0, .0, 1.0));

}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - iResolution.xy * 0.5) / iResolution.y;
    vec3 effectColor = vec3(0.0);
    vec3 ro,rd;
// SETUP
    float epoch = 13.0;
    float locTime = mod(iTime, epoch);
    float epochnum = floor(iTime / epoch);

    // Camera setup

    vec3 cam_pos0 = randomVec3(vec2(epochnum, 0.2), vec3(0.0), vec3(1.0));
    cam_pos0.z=-1000.0;
    vec3 cam_pos1 = randomVec3(vec2(epochnum, 0.1), vec3(0.0), vec3(1.0));
    cam_pos1.z = -8.0;
    vec3 cam_pos2 = vec3(0.0,0.0,-0.8);
    float inittime = 4.0;
    float exittime = 10.0;

    // vec3(.5,.3,0.9)
    vec3 orbit_point = randomVec3(vec2(epochnum, 19.9), vec3(.0), vec3(1.0));
    orbit_point.z=-0.2;

    ro = rayscene_orbit(vec3(0.0,0.0,0.0), cam_pos1, (1.0*3.141)/(epoch), orbit_point, locTime-exittime, 0.0);
    if (locTime < inittime) {
        ro = flightPathEase(cam_pos0, ro, locTime+1.0, inittime);
    } 
    if (locTime > exittime) {
        ro = flightPathAccel(ro, cam_pos2, locTime-exittime, 3.0);
    }
    rd = rd_towards_point(vec3(0.0), ro, uv);

    if (locTime < 0.7) {
        effectColor = flash_color(locTime, uv, 0.2, 2.0, 0.6);
    }
    if (locTime > epoch-0.3) {
        effectColor = flash_color(locTime - 9.7, uv, 0.2, 1.0, 0.6);
    }


    // Light setup
    vec3 lightPos = vec3(2.0, 2.0, -3.0);
    vec3 lightColor = vec3(1.0);


    Sphere spheres[NUM_SPHERES];
    SphereMinus2 s2ms[NUM_SM2S];
    rayscene_buildScene(spheres, s2ms, locTime, epochnum);

// RENDER LOOP

    Ray ray = Ray(ro, rd);

    vec3 finalColor = vec3(0.0);

    IntersectionResult ir = raytrace_traceRay(ray, spheres, s2ms);   
    if (ir.hit) {
        // special texture col
        vec3 texture_col = vec3(1);
        vec3 polar = cartesianToPolar(ir.n);
        if (ir.type == 1 && ir.index>1) {
            texture_col = surface_plasma(polar.y, polar.z, iTime, ir.index, 1);
        } else if (ir.type == 1 && ir.index<2) {
            texture_col = surface_nebula(vec2(polar.y,polar.z), 3.2*float(ir.index+1));
        } else {
            texture_col = vec3(1.0);
        }

        finalColor = calculateLighting(ray, ir.hitpoint, ir.n, lightPos, lightColor, texture_col + ir.col);        
    } else {
        // skysphere
        vec3 nebula_col = randomVec3(vec2(epochnum, 0.2), vec3(0.0), vec3(0.1));
        Sphere background = Sphere(vec3(0.0,0.0,0.0), 1e6, nebula_col);
        IntersectionResult back_ir = raytrace_intersectSphere(ray, background);
        if (back_ir.hit) {
            vec3 polar = cartesianToPolar(back_ir.n);
            vec3 texture_col = surface_nebula(polar.yz, 2.2);
            finalColor = texture_col + back_ir.col;
            //finalColor = vec3(theta, 0.0, phi);
        } else finalColor = vec3(1.0);
    }

    fragColor = vec4(max(finalColor, effectColor), 1.0);
}
